Let us choose $R_2=R_2(\lambda, L, T)$ as in Lemma \ref{lemma_ground_is_mostly_fertile} and let us consider any $R \geq R_2$,
$n \in \mathbb{N}$ and any $\mathcal{T} \in \Lambda_{n,L}$. Let
\begin{equation}\label{Y_n_prome_def}
  Y'_n:=  \sum_{x \in \mathcal{X} } \left( \zeta(x) - \zeta^{*}(x) \right)\epsilon(x), \qquad s:=\left(2^{|B(2L)|+1} C_d \right)^9.
\end{equation}
  It is enough to prove
 \begin{equation}\label{momgen_ineq}
 \mathbb{E} \left( s^{Y'_n} \right)  \leq 2^{ |B(2L)| 2^n},
 \end{equation}
  because then  $\mathbb{P}\left( Y'_n \geq \frac{1}{9} 2^n  \right) \leq  \left( 2 C_d  \right)^{-2^n}$ follows by the exponential Chebyshev's inequality, and this bound together with \eqref{ground_is_mostly_fertile_eq} implies  \eqref{survival_to_T_suffices_eq}.




In order to prove \eqref{momgen_ineq},
we  define the sigma-algebra $\mathcal{G}$ generated by the random variables $(Z_t(x,y)), x \in \mathcal{X}, y \in \mathbb{Z}^d, 0 \leq t \leq T$ and $(\xi^{* \hspace{-.05cm} *}(y) )_{y \in \mathbb{Z}^d}$.

 Note that it follows from the definitions  \eqref{zeta_def_supcrit}, \eqref{def_omega_balazs} and \eqref{def_epsilon_bad_event} that
 \begin{equation}\label{G_measurable}
 \left(\zeta(x)\right)_{x \in \mathcal{X}}, \; \left(\omega(z)\right)_{z \in \mathbb{Z}^d}, \; \; \left(\epsilon(x)\right)_{x \in \mathcal{X}}\;
 \text{ are all $\mathcal{G}$-measurable.}
 \end{equation}
  Observe that
\begin{equation}\label{condindep_zeta_star}
 \zeta^*(x), x \in \mathcal{X} \text{ are conditionally independent given } \mathcal{G},
\end{equation}
 since the BRW particles used in the definition of $\zeta^*(x), x\in \mathcal{X}$ (cf.\ \eqref{zeta_star})  reproduce and die independently from each other and $\xi^{* \hspace{-.05cm} *}$ on $[T,T+1]$  (cf.\ Definitions \ref{def_brw_from_X} and \ref{def_ingredients_supercrit}).
Recalling the definitions of $p_*$ from \eqref{p_star} and $Z_T(x)$ from \eqref{Z_T_x},  we will prove
\begin{equation}\label{condexp_fertile_landing}
  \mathbb{E}\left( \left(\zeta(x) - \zeta^{*}(x) \right)\epsilon(x) \,   | \,  \mathcal{G} \right) \leq  p_*^{Z_T(x)} \zeta(x), \qquad x \in \mathcal{X}.
\end{equation}
 Before we show \eqref{condexp_fertile_landing}, let us deduce \eqref{momgen_ineq} from it:
\begin{multline} \label{here_is_where_we_use_many_children}
 \mathbb{E} \left( s^{Y'_n} \right)
   \stackrel{ \eqref{Y_n_prome_def} }{=}
   \mathbb{E} \left( \mathbb{E} \left( \prod_{x \in \mathcal{X} } s^{\left( \zeta(x) - \zeta^{*}(x) \right)\epsilon(x)} \, \big| \, \mathcal{G} \right) \right)
   \stackrel{ \eqref{G_measurable}, \eqref{condindep_zeta_star} }{=}
   \\
 \mathbb{E} \left(  \prod_{x \in \mathcal{X} } \mathbb{E} \left(  s^{\left( \zeta(x) - \zeta^{*}(x) \right)\epsilon(x)} \, \big| \, \mathcal{G} \right) \right)
    \stackrel{ \eqref{zeta_geq_zeta_star}, \eqref{condexp_fertile_landing} }{\leq } \mathbb{E}\left( \prod_{x \in \mathcal{X} }  \left( s p_*^{Z_T(x)} \zeta(x) +1  \right) \right)
    \stackrel{ \eqref{zeta_def_supcrit} }{=}
    \\
   \prod_{x \in \mathcal{X} }  \mathbb{E}  \left( s p_*^{Z_T(x)} \mathds{1}\left[ \, 0<  Z_T(x)  \, \right] +1  \right)
   \stackrel{ \eqref{many_children_Z_T}, \eqref{Y_n_prome_def} }{\leq } \prod_{x \in \mathcal{X} }   \left( 1 +1  \right)
   \stackrel{ \eqref{disjoint_X_cardinality} }{=} 2^{  |B(2L)| 2^n }.
\end{multline}
It remains to show \eqref{condexp_fertile_landing}. We begin by observing that
\begin{multline}\label{fertile_landing_alternate_form}
 \mathbb{E}\left( \left(\zeta(x) - \zeta^{*}(x) \right)\epsilon(x) \,   | \,  \mathcal{G} \right) \stackrel{\eqref{zeta_geq_zeta_star}, \eqref{G_measurable} }{=}
 \mathbb{E}\left( 1 - \zeta^{*}(x) \,   | \,  \mathcal{G} \right) \zeta(x) \epsilon(x)\stackrel{ \eqref{zeta_star} }{=} \\
   \mathbb{P}\left(\, \forall y' \in \mathbb{Z}^d \, : \;  Z_{T+1}(x,y') \cdot  \xi^{* \hspace{-.05cm} *}(y')=0
       \, \big| \,  \mathcal{G}\, \right) \zeta(x) \epsilon(x).
\end{multline}
The goal is to upper bound the r.h.s.\ of \eqref{fertile_landing_alternate_form} by  $p_*^{Z_T(x)} \zeta(x)$. At time $T$ there are $Z_T(x)$ BRW particles with label $x$, so it is enough to show that if $\epsilon(x)=1$ then each of these particles, with probability at least $1-p_*$, independently from the others, will produce an offspring which is located at a site
 with positive $\xi^{* \hspace{-.05cm} *}$ value at time $T+1$. In order to show this, first
observe that if $\epsilon(x)=1$ then for any $y$ the condition $Z_T(x,y)>0$ implies $\omega\left( \lfloor \frac{y}{\kappa R} \rfloor \right)=1$ (cf.\ \eqref{def_epsilon_bad_event}), which in turn implies
  $\sum_{y' \in B(y,R)} \xi^{* \hspace{-.05cm} *}(y') \geq \alpha R^d$ (cf.\  \eqref{def_omega_balazs}). So if there is a particle at time $T$ at location $y$, which
  \begin{enumerate}[(i)]
  \item \label{i_success} does not die in $[T,T+1]$,
  \item \label{ii_success} produces at least one child in $[T,T+1]$,
  \item \label{iii_success} this child lands at a site $y'$ with $\xi^{* \hspace{-.05cm} *}(y')=1$,
  \item \label{iiii_success} this child does not die until $T+1$,
\end{enumerate}
then $Z_{T+1}(x,y') \cdot  \xi^{* \hspace{-.05cm} *}(y')>0$. Now \eqref{i_success} occurs with probability $e^{-1}$, given this \eqref{ii_success} occurs
with probability $1-e^{-\lambda}$, given this \eqref{iii_success} occurs with probability at least $\alpha R^d /|B(R)| \geq \alpha / 3^d$, given this
\eqref{iiii_success} occurs with probability at least $e^{-1}$. Altogether, the probability that \eqref{i_success}-\eqref{iiii_success} all occur is at least $1-p_*$ (cf.\
