&\doublehat{\eta}_1(z) = Z(z,1)\cdot \max\left(Z(z,0)\cdot \doublehat{\eta}_0(z),\;Z(z-1,0) \cdot \doublehat{\eta}_0(z-1)\right),\\[.2cm]
&\doublehat{\eta}_{n+1}(z) = Z(z,n+1) \cdot \max\left(\doublehat{\eta}_n(z),\; \doublehat{\eta}_n(z-1)\right),\quad n \geq 1.
\end{align*}

\begin{equation*}
P_{p,\Psi}\left( \eta_n^{[0,k]} \cap \eta'=\varnothing  \right)=
P_{p,\Psi}\left( \hat{\eta}_{n-1}^{[-1,k]} \cap \eta'=\varnothing  \right)=
P_{p,\Psi}\left( \doublehat{\eta}_{n-1}^{\mathcal{A}'} \cap [-1,k]=\varnothing  \right),
\end{equation*}
